{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE MAPLEMONK.FYTIKA_DB_PRODUCT_MARKETING_CONSOLIDATED AS WITH sales AS ( SELECT distinct order_date, CAST(product_id AS STRING) AS product_id, SKU, SUM(IFNULL(selling_price,0)) AS sales FROM `maplemonk.maplemonk_analytics_sales_consolidated` GROUP BY 1,2,3 ), shopify AS ( SELECT distinct CAST(PRODUCT_ID AS STRING) AS PRODUCT_ID, CAST(VARIANT_ID AS STRING) AS VARIANT_ID, CAST(SKU AS STRING) AS SKU, CAST(Product_Category AS STRING) AS Product_Category FROM maplemonk.maplemonk_analytics_SHOPIFY_FACT_ITEMS QUALIFY ROW_NUMBER() OVER (PARTITION BY SKU ORDER BY Product_Category) = 1 ), sku_map AS ( SELECT * FROM `maplemonk-analytics.maplemonk.unicommerce_fytika_get_product_listing` WHERE mrp IS NOT NULL QUALIFY ROW_NUMBER() OVER (PARTITION BY channel_product_id ORDER BY DATE(updated) DESC) = 1 ), marketing_consolidated AS ( SELECT LOWER(TRIM(channel)) AS channel, DATE(date) AS date, SUM(CAST(spend AS FLOAT64)) AS total_channel_spend FROM `maplemonk.maplemonk_analytics_MARKETING_CONSOLIDATED` GROUP BY 1,2 ), product_master AS ( SELECT distinct product_code, name, category_name FROM maplemonk-analytics.maplemonk.unicommerce_fytika_get_product_master QUALIFY ROW_NUMBER() OVER (PARTITION BY product_code ORDER BY DATE(updated) DESC) = 1 ), facebook AS ( SELECT CAST(fc.Adset_Name AS STRING) AS ADSET_NAME, CAST(fc.Adset_ID AS STRING) AS ADSET_ID, CAST(fc.ad_id AS STRING) AS AD_ID, CAST(fc.ad_name AS STRING) AS AD_NAME, CAST(fc.Account_Name AS STRING) AS ACCOUNT_NAME, CAST(fc.Account_ID AS STRING) AS ACCOUNT_ID, CAST(fc.Campaign_Name AS STRING) AS CAMPAIGN_NAME, CAST(fc.Campaign_ID AS STRING) AS CAMPAIGN_ID, CAST(fc.product_id AS STRING) AS PRODUCT_ID, cast(null as string) AS VARIANT_ID, DATE(fc.Date) AS DATE, CAST(NULL AS STRING) AS AD_TYPE, CAST(NULL AS STRING) AS AD_STRENGTH, CAST(NULL AS STRING) AS AD_NETWORK_TYPE, CAST(NULL AS STRING) AS AD_FINAL_URL, FORMAT_DATE(\'%A\', DATE(fc.Date)) AS DAY_OF_WEEK, EXTRACT(YEAR FROM DATE(fc.Date)) AS YEAR, EXTRACT(MONTH FROM DATE(fc.Date)) AS MONTH, CAST(fc.Channel AS STRING) AS CHANNEL, CAST(fc.Account AS STRING) AS ACCOUNT, SUM(CAST(fc.Clicks AS FLOAT64)) AS CLICKS, SUM(CAST(fc.Spend AS FLOAT64)) AS SPEND, SUM(CAST(fc.Impressions AS FLOAT64)) AS IMPRESSIONS, SUM(CAST(fc.Conversions AS FLOAT64)) AS CONVERSIONS, SUM(CAST(fc.Conversion_Value AS FLOAT64)) AS CONVERSION_VALUE, SUM(IFNULL(sl.sales,0)) AS SALES, LOWER(TRIM(sm.sku_code)) AS SKU FROM maplemonk.fytika_db_Product_FACEBOOK_CONSOLIDATED fc LEFT JOIN sku_map sm ON CAST(fc.product_id AS STRING) = sm.channel_product_id left join sales sl on trim(lower(sm.sku_code)) = trim(lower(sl.sku)) and upper(sm.channelname) like \'%SHOPIFY%\' GROUP BY ALL ), google AS ( SELECT CAST(gc.ADSET_NAME AS STRING) AS ADSET_NAME, CAST(gc.ADSET_ID AS STRING) AS ADSET_ID, CAST(gc.AD_ID AS STRING) AS AD_ID, CAST(gc.AD_NAME AS STRING) AS AD_NAME, CAST(gc.ACCOUNT_NAME AS STRING) AS ACCOUNT_NAME, CAST(gc.ACCOUNT_ID AS STRING) AS ACCOUNT_ID, CAST(gc.CAMPAIGN_NAME AS STRING) AS CAMPAIGN_NAME, CAST(gc.CAMPAIGN_ID AS STRING) AS CAMPAIGN_ID, CAST(SPLIT(gc.segments_product_item_id, \'_\')[SAFE_OFFSET(2)] AS STRING) AS PRODUCT_ID, CAST(SPLIT(gc.segments_product_item_id, \'_\')[SAFE_OFFSET(3)] AS STRING) AS VARIANT_ID, DATE(gc.Date) AS DATE, CAST(gc.AD_TYPE AS STRING) AS AD_TYPE, CAST(gc.AD_STRENGTH AS STRING) AS AD_STRENGTH, CAST(gc.AD_NETWORK_TYPE AS STRING) AS AD_NETWORK_TYPE, CAST(gc.AD_FINAL_URL AS STRING) AS AD_FINAL_URL, CAST(gc.DAY_OF_WEEK AS STRING) AS DAY_OF_WEEK, CAST(gc.YEAR AS INT64) AS YEAR, CAST(gc.MONTH AS INT64) AS MONTH, CAST(gc.Channel AS STRING) AS CHANNEL, CAST(gc.Account AS STRING) AS ACCOUNT, SUM(CAST(gc.clicks AS FLOAT64)) AS CLICKS, SUM(CAST(gc.spend AS FLOAT64)) AS SPEND, SUM(CAST(gc.Impressions AS FLOAT64)) AS IMPRESSIONS, SUM(CAST(gc.Conversions AS FLOAT64)) AS CONVERSIONS, SUM(CAST(gc.Conversion_Value AS FLOAT64)) AS CONVERSION_VALUE, SUM(IFNULL(sl.sales,0)) AS SALES, LOWER(TRIM(sm.sku_code)) AS SKU FROM maplemonk.Fytika_db_Product_GOOGLEADS_CONSOLIDATED gc LEFT JOIN sku_map sm ON coalesce(CAST(SPLIT(gc.segments_product_item_id, \'_\')[SAFE_OFFSET(2)] AS STRING), CAST(SPLIT(gc.segments_product_item_id, \'_\')[SAFE_OFFSET(3)] AS STRING)) = sm.channel_product_id left join sales sl on trim(lower(cast(sm.sku_code as string))) = trim(lower(cast(sl.sku as string))) and upper(sm.channelname) like \'%SHOPIFY%\' GROUP BY ALL ), amazon_channel_spend AS ( SELECT LOWER(\'amazon\') AS channel, DATE(date) AS date, SUM(CAST(spend AS FLOAT64)) AS total_channel_spend FROM `maplemonk-analytics.maplemonk.fytika_AMAZON_ADS_HOURLY_DATA_CONSOLIDATED` GROUP BY 1,2 ), amazon AS ( SELECT CAST(NULL AS STRING) AS ADSET_NAME, CAST(NULL AS STRING) AS ADSET_ID, CAST(a.AD_ID AS STRING) AS AD_ID, CAST(a.NAME AS STRING) AS AD_NAME, CAST(a.NAME AS STRING) AS ACCOUNT_NAME, CAST(a.PROFILEID AS STRING) AS ACCOUNT_ID, CAST(a.CAMPAIGNNAME AS STRING) AS CAMPAIGN_NAME, CAST(a.CAMPAIGN_ID AS STRING) AS CAMPAIGN_ID, CAST(a.channel_product_id AS STRING) AS PRODUCT_ID, cast(null as string) AS VARIANT_ID, a.DATE AS DATE, CAST(a.AD_TYPE_1 AS STRING) AS AD_TYPE, CAST(NULL AS STRING) AS AD_STRENGTH, CAST(NULL AS STRING) AS AD_NETWORK_TYPE, CAST(NULL AS STRING) AS AD_FINAL_URL, FORMAT_DATE(\'%A\', a.DATE) AS DAY_OF_WEEK, EXTRACT(YEAR FROM a.DATE) AS YEAR, EXTRACT(MONTH FROM a.DATE) AS MONTH, CAST(\'Amazon\' AS STRING) AS CHANNEL, CAST(a.NAME AS STRING) AS ACCOUNT, a.clicks AS CLICKS, a.spend AS SPEND, a.impressions AS IMPRESSIONS, a.conversions AS CONVERSIONS, a.conversion_value AS CONVERSION_VALUE, IFNULL(sl.sales,0) AS SALES, LOWER(TRIM(sm.sku_code)) AS SKU FROM ( SELECT AD_ID, NAME, PROFILEID, CAMPAIGNNAME, CAMPAIGN_ID, channel_product_id, sku_code, DATE(Date) AS DATE, AD_TYPE_1, SUM(clicks) clicks, SUM(spend) spend, SUM(Impressions) impressions, SUM(ATTRIBUTED_CONVERSIONS_14D) conversions, SUM(ATTRIBUTED_SALES_14D) conversion_value FROM `maplemonk-analytics.maplemonk.fytika_AMAZON_ADS_HOURLY_DATA_CONSOLIDATED` WHERE channel_product_id IS NOT NULL GROUP BY 1,2,3,4,5,6,7,8,9 ) a LEFT JOIN sku_map sm ON a.channel_product_id = sm.channel_product_id left join sales sl on trim(lower(cast(sm.sku_code as string))) = trim(lower(cast(sl.sku as string))) and upper(sm.channelname) like \'%AMAZON%\' ), flipkart AS ( SELECT CAST(fk.Adset_Name AS STRING) AS ADSET_NAME, CAST(fk.Adset_ID AS STRING) AS ADSET_ID, CAST(fk.ad_id AS STRING) AS AD_ID, CAST(fk.ad_name AS STRING) AS AD_NAME, CAST(fk.Account_Name AS STRING) AS ACCOUNT_NAME, CAST(fk.Account_ID AS STRING) AS ACCOUNT_ID, CAST(fk.Campaign_Name AS STRING) AS CAMPAIGN_NAME, CAST(fk.Campaign_ID AS STRING) AS CAMPAIGN_ID, CAST(fk.product_id AS STRING) AS PRODUCT_ID, CAST(fk.VARIANT_ID AS STRING) AS VARIANT_ID, fk.DATE AS DATE, CAST(NULL AS STRING) AS AD_TYPE, CAST(NULL AS STRING) AS AD_STRENGTH, CAST(NULL AS STRING) AS AD_NETWORK_TYPE, CAST(NULL AS STRING) AS AD_FINAL_URL, FORMAT_DATE(\'%A\', fk.Date) AS DAY_OF_WEEK, EXTRACT(YEAR FROM fk.Date) AS YEAR, EXTRACT(MONTH FROM fk.Date) AS MONTH, CAST(fk.Channel AS STRING) AS CHANNEL, CAST(fk.Account AS STRING) AS ACCOUNT, SUM(CAST(fk.Clicks AS FLOAT64)) AS CLICKS, SUM(CAST(fk.Spend AS FLOAT64)) AS SPEND, SUM(CAST(fk.Impressions AS FLOAT64)) AS IMPRESSIONS, SUM(CAST(fk.Conversions AS FLOAT64)) AS CONVERSIONS, SUM(CAST(fk.Conversion_Value AS FLOAT64)) AS CONVERSION_VALUE, SUM(CAST(fk.SALES AS FLOAT64)) AS SALES, LOWER(TRIM(fk.sku)) AS SKU FROM maplemonk.Fytika_db_Product_Flipkart_FSN fk GROUP BY ALL ), marketing_consolidated_product_intermediate AS ( SELECT * FROM facebook UNION ALL SELECT * FROM google UNION ALL SELECT * FROM amazon UNION ALL SELECT * FROM flipkart ) SELECT m.*, UPPER(pm.name) AS PRODUCT_NAME, UPPER(CAST(pm.CATEGORY_name AS STRING)) AS PRODUCT_CATEGORY, IFNULL(SUM(m.SPEND) OVER (PARTITION BY m.DATE, m.CHANNEL), 0) AS total_product_lvl_spend, IFNULL(CASE WHEN LOWER(m.channel) LIKE \'%amazon%\' THEN ac.total_channel_spend ELSE mc.total_channel_spend END, 0) AS total_channel_spend, IFNULL(CASE WHEN LOWER(m.channel) LIKE \'%amazon%\' THEN ac.total_channel_spend ELSE mc.total_channel_spend END, 0) - IFNULL(SUM(m.SPEND) OVER (PARTITION BY m.DATE, m.CHANNEL), 0) AS spend_diff, CASE WHEN SUM(m.SALES) OVER (PARTITION BY m.DATE, m.CHANNEL) != 0 THEN ((CASE WHEN LOWER(m.channel) = \'amazon\' THEN ac.total_channel_spend ELSE mc.total_channel_spend END) - SUM(m.SPEND) OVER (PARTITION BY m.DATE, m.CHANNEL)) * (m.SALES / SUM(m.SALES) OVER (PARTITION BY m.DATE, m.CHANNEL)) ELSE 0 END AS allocated_spend_diff, CASE WHEN SUM(m.SALES) OVER (PARTITION BY m.DATE, m.CHANNEL) != 0 THEN m.SPEND + (((CASE WHEN LOWER(m.channel) = \'amazon\' THEN ac.total_channel_spend ELSE mc.total_channel_spend END) - SUM(m.SPEND) OVER (PARTITION BY m.DATE, m.CHANNEL)) * (m.SALES / SUM(m.SALES) OVER (PARTITION BY m.DATE, m.CHANNEL))) ELSE SPEND END AS corrected_spend FROM marketing_consolidated_product_intermediate m LEFT JOIN marketing_consolidated mc ON LOWER(TRIM(m.channel)) = mc.channel AND m.date = mc.date LEFT JOIN amazon_channel_spend ac ON LOWER(TRIM(m.channel)) = ac.channel AND m.date = ac.date LEFT JOIN product_master pm ON trim(lower(pm.product_code)) = trim(lower(m.sku));",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from maplemonk.INFORMATION_SCHEMA.TABLES
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            